package com.secretnotes;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;
public class SettingsActivity extends Activity { public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_settings);findViewById(R.id.changePin).setOnClickListener(v->changePin());findViewById(R.id.about).setOnClickListener(v->startActivity(new Intent(this,AboutActivity.class)));findViewById(R.id.theme).setOnClickListener(v->{getSharedPreferences("ui",0).edit().putBoolean("light",!getSharedPreferences("ui",0).getBoolean("light",false)).apply();Toast.makeText(this,"Theme changed. Reopen the app to apply it.",Toast.LENGTH_SHORT).show();});}
 void changePin(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(48,8,48,0);EditText old=new EditText(this);old.setHint("Current PIN");old.setInputType(2);EditText n=new EditText(this);n.setHint("New 4-digit PIN");n.setInputType(2);l.addView(old);l.addView(n);new AlertDialog.Builder(this).setTitle("Change PIN").setView(l).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->{if(!new SecurePrefs(this).verify(old.getText().toString()))old.setError("Incorrect PIN");else if(n.getText().toString().matches("\\d{4}")){new SecurePrefs(this).setPin(n.getText().toString());Toast.makeText(this,"PIN updated",Toast.LENGTH_SHORT).show();}else n.setError("Enter 4 digits");}).show();}}
